module game_solver(\n    input clk,\n    input rst_n,\n    input start,\n    input [127:0] packed_s,\n    input [4:0] len,\n    output reg [15:0] winner,\n    output reg done\n);\n\n    // State declarations\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] FINISH = 2'd2;\n    \n    reg [1:0] state;\n    reg [4:0] k;\n    reg [7:0] current_char;\n    reg [7:0] min_char;\n    reg [15:0] winner_reg;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            k <= 5'd0;\n            min_char <= 8'hFF;\n            winner_reg <= 16'd0;\n            done <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= COMPUTE;\n                        k <= 5'd0;\n                        min_char <= 8'hFF;\n                        winner_reg <= 16'd0;\n                    end\n                end\n                \n                COMPUTE: begin\n                    if (k < len) begin\n                        current_char = packed_s[k*8 +: 8];\n                        winner_reg[k] <= (min_char < current_char);\n                        min_char <= (min_char < current_char) ? min_char : current_char;\n                        k <= k + 5'd1;\n                    end else begin\n                        winner <= winner_reg;\n                        done <= 1'b1;\n                        state <= FINISH;\n                    end\n                end\n                \n                FINISH: begin\n                    done <= 1'b0;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule